## 10/10/2026 10:56 — PC Investigation Stage 2

Run this in the **same Administrator PowerShell**. It is still **collection only**: no killing processes, disabling extensions, deleting files, or changing configuration.

```powershell
$O="$env:USERPROFILE\Desktop\PC_CHECK_STAGE2_$(Get-Date -Format yyyyMMdd_HHmmss).txt"

"=== STAGE 2 SNAPSHOT $(Get-Date) ===" | Out-File $O

"`n========== 1. ESTABLISHED NETWORK CONNECTIONS + PROCESS ==========" | Out-File $O -Append
Get-NetTCPConnection -State Established -ErrorAction SilentlyContinue | ForEach-Object {
    $n=$_
    $p=Get-CimInstance Win32_Process -Filter "ProcessId=$($n.OwningProcess)" -ErrorAction SilentlyContinue
    [PSCustomObject]@{
        PID=$n.OwningProcess
        Process=$p.Name
        Executable=$p.ExecutablePath
        Local="$($n.LocalAddress):$($n.LocalPort)"
        Remote="$($n.RemoteAddress):$($n.RemotePort)"
        CommandLine=$p.CommandLine
    }
} | Sort-Object Process,PID | Format-List | Out-String -Width 600 | Out-File $O -Append


"`n========== 2. LISTENING PORTS + PROCESS ==========" | Out-File $O -Append
Get-NetTCPConnection -State Listen -ErrorAction SilentlyContinue | ForEach-Object {
    $n=$_
    $p=Get-CimInstance Win32_Process -Filter "ProcessId=$($n.OwningProcess)" -ErrorAction SilentlyContinue
    [PSCustomObject]@{
        PID=$n.OwningProcess
        Process=$p.Name
        Executable=$p.ExecutablePath
        Listen="$($n.LocalAddress):$($n.LocalPort)"
        CommandLine=$p.CommandLine
    }
} | Sort-Object Process,PID | Format-List | Out-String -Width 600 | Out-File $O -Append


"`n========== 3. NON-MICROSOFT RUNNING EXECUTABLE SIGNATURES ==========" | Out-File $O -Append
Get-CimInstance Win32_Process |
Where-Object {$_.ExecutablePath} |
Select-Object -ExpandProperty ExecutablePath -Unique |
ForEach-Object {
    $path=$_
    try {
        $sig=Get-AuthenticodeSignature -FilePath $path -ErrorAction Stop
        [PSCustomObject]@{
            Path=$path
            SignatureStatus=$sig.Status
            Signer=if($sig.SignerCertificate){$sig.SignerCertificate.Subject}else{""}
        }
    } catch {
        [PSCustomObject]@{
            Path=$path
            SignatureStatus="ERROR"
            Signer=""
        }
    }
} | Where-Object {
    $_.Signer -notmatch "Microsoft Windows|Microsoft Corporation"
} | Sort-Object SignatureStatus,Path |
Format-List | Out-String -Width 600 | Out-File $O -Append


"`n========== 4. EDGE EXTENSIONS ==========" | Out-File $O -Append
$edge="$env:LOCALAPPDATA\Microsoft\Edge\User Data"
if(Test-Path $edge){
    Get-ChildItem $edge -Directory -ErrorAction SilentlyContinue |
    Where-Object {$_.Name -match '^Default$|^Profile '} |
    ForEach-Object {
        $profile=$_.Name
        $extPath=Join-Path $_.FullName "Extensions"
        if(Test-Path $extPath){
            Get-ChildItem $extPath -Directory -ErrorAction SilentlyContinue |
            ForEach-Object {
                $id=$_.Name
                Get-ChildItem $_.FullName -Directory -ErrorAction SilentlyContinue |
                ForEach-Object {
                    $manifest=Join-Path $_.FullName "manifest.json"
                    if(Test-Path $manifest){
                        try {
                            $m=Get-Content $manifest -Raw | ConvertFrom-Json
                            [PSCustomObject]@{
                                Profile=$profile
                                ExtensionID=$id
                                Name=$m.name
                                Version=$m.version
                                Permissions=($m.permissions -join ", ")
                                HostPermissions=($m.host_permissions -join ", ")
                            }
                        } catch {}
                    }
                }
            }
        }
    } | Format-List | Out-String -Width 600 | Out-File $O -Append
}


"`n========== 5. CHROME EXTENSIONS ==========" | Out-File $O -Append
$chrome="$env:LOCALAPPDATA\Google\Chrome\User Data"
if(Test-Path $chrome){
    Get-ChildItem $chrome -Directory -ErrorAction SilentlyContinue |
    Where-Object {$_.Name -match '^Default$|^Profile '} |
    ForEach-Object {
        $profile=$_.Name
        $extPath=Join-Path $_.FullName "Extensions"
        if(Test-Path $extPath){
            Get-ChildItem $extPath -Directory -ErrorAction SilentlyContinue |
            ForEach-Object {
                $id=$_.Name
                Get-ChildItem $_.FullName -Directory -ErrorAction SilentlyContinue |
                ForEach-Object {
                    $manifest=Join-Path $_.FullName "manifest.json"
                    if(Test-Path $manifest){
                        try {
                            $m=Get-Content $manifest -Raw | ConvertFrom-Json
                            [PSCustomObject]@{
                                Profile=$profile
                                ExtensionID=$id
                                Name=$m.name
                                Version=$m.version
                                Permissions=($m.permissions -join ", ")
                                HostPermissions=($m.host_permissions -join ", ")
                            }
                        } catch {}
                    }
                }
            }
        }
    } | Format-List | Out-String -Width 600 | Out-File $O -Append
}


"`n========== 6. STARTUP REGISTRY ==========" | Out-File $O -Append
$runKeys=@(
'HKCU:\Software\Microsoft\Windows\CurrentVersion\Run',
'HKCU:\Software\Microsoft\Windows\CurrentVersion\RunOnce',
'HKLM:\Software\Microsoft\Windows\CurrentVersion\Run',
'HKLM:\Software\Microsoft\Windows\CurrentVersion\RunOnce',
'HKLM:\Software\WOW6432Node\Microsoft\Windows\CurrentVersion\Run'
)

foreach($key in $runKeys){
    "`n--- $key ---" | Out-File $O -Append
    if(Test-Path $key){
        Get-ItemProperty $key |
        Format-List |
        Out-String -Width 600 |
        Out-File $O -Append
    }
}


"`n========== 7. RECENT SYSTEM EVENTS 10:30-11:05 ==========" | Out-File $O -Append
$start=[datetime]"2026-10-10 10:30:00"
$end=[datetime]"2026-10-10 11:05:00"

Get-WinEvent -FilterHashtable @{
    LogName='System'
    StartTime=$start
    EndTime=$end
} -ErrorAction SilentlyContinue |
Select-Object TimeCreated,Id,LevelDisplayName,ProviderName,Message |
Format-List | Out-String -Width 600 | Out-File $O -Append


"`n========== 8. RECENT APPLICATION EVENTS 10:30-11:05 ==========" | Out-File $O -Append
Get-WinEvent -FilterHashtable @{
    LogName='Application'
    StartTime=$start
    EndTime=$end
} -ErrorAction SilentlyContinue |
Select-Object TimeCreated,Id,LevelDisplayName,ProviderName,Message |
Format-List | Out-String -Width 600 | Out-File $O -Append


"`n========== 9. POWERSHELL OPERATIONAL EVENTS 10:30-11:05 ==========" | Out-File $O -Append
Get-WinEvent -FilterHashtable @{
    LogName='Microsoft-Windows-PowerShell/Operational'
    StartTime=$start
    EndTime=$end
} -ErrorAction SilentlyContinue |
Select-Object TimeCreated,Id,LevelDisplayName,Message |
Format-List | Out-String -Width 600 | Out-File $O -Append


"`n========== 10. CURRENT LOGON SESSIONS ==========" | Out-File $O -Append
quser 2>&1 | Out-File $O -Append


"`n========== 11. REMOTE DESKTOP CONFIGURATION ==========" | Out-File $O -Append
Get-ItemProperty 'HKLM:\SYSTEM\CurrentControlSet\Control\Terminal Server' -ErrorAction SilentlyContinue |
Select-Object fDenyTSConnections |
Format-List | Out-String | Out-File $O -Append


"`n========== 12. FIREWALL PROFILES ==========" | Out-File $O -Append
Get-NetFirewallProfile |
Select-Object Name,Enabled,DefaultInboundAction,DefaultOutboundAction |
Format-Table -AutoSize |
Out-String | Out-File $O -Append


"`n========== FINISHED ==========" | Out-File $O -Append

Write-Host ""
Write-Host "STAGE 2 COMPLETE"
Write-Host $O
```

### What this stage adds

The important difference is that Stage 1 told us **“these things exist.”** Stage 2 starts connecting the evidence:

**Internet connection → PID → process → executable → command line**

and separately:

**running executable → digital-signature status/signer.**

It also enumerates **Edge and Chrome extensions and their requested permissions**, checks common startup registry locations, examines Windows events specifically around **10:30–11:05**, checks current Windows logon sessions and whether Remote Desktop is enabled.

One clarification: section 3's heading says *non-Microsoft*, but the filtering is based on the certificate signer text. Treat it as a **triage list**, not proof that every item listed is third-party or suspicious.

